from collections import deque
def f(g):
    R=len(g); C=len(g[0])
    g=[row[:] for row in g]
    # source: cells not reachable to grid border through non-5 cells? Use BFS from border cells that are 0, expanding through 0s; track distance to nearest source
    dist=[[None]*C for _ in range(R)]
    q=deque()
    for i in range(R):
        for j in (0,C-1):
            if g[i][j]==0: dist[i][j]=0;q.append((i,j))
    for j in range(C):
        for i in (0,R-1):
            if g[i][j]==0: dist[i][j]=0;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<R and 0<=nj<C and g[ni][nj]==0 and dist[ni][nj] is None:
                dist[ni][nj]=dist[i][j]+1; q.append((ni,nj))
    for i in range(R):
        for j in range(C):
            if g[i][j]==0 and dist[i][j] is not None:
                v=dist[i][j]
                if v==1: g[i][j]=2
                elif v==2: g[i][j]=5
    return g
